class Component extends DCLogic {
  componentDidMount(){ const go=()=>window.SWD?SWD.ready(()=>this.init()):setTimeout(go,30); go(); }
  init(){
    const D=SW_DEMO_DATA, CF=SW_DEMO, $=id=>document.getElementById(id), UF=SWD.UFS(), CT=CF.country, T=D.ts, RC=D.rc;
    SWD.page({active:'vital',lv:'BR',label:'Nascimentos e mortes'});
    const st={l:SWD.q.get('u')||'BR',hov:null};
    $('place').innerHTML=`<option value="BR">${CT.name}</option>`+UF.slice().sort((a,b)=>SWD.name(a).localeCompare(SWD.name(b))).map(u=>`<option value="${u}">${SWD.name(u)}</option>`).join('');
    $('place').onchange=e=>{st.l=e.target.value; draw()};
    $('vstamp').innerHTML=SWD.stamp('rc'); $('src').innerHTML=SWD.srcLine(['rc','proj']);
    const ratio=u=>RC.nasc[u]&&RC.obit[u]?RC.nasc[u]['2024']/RC.obit[u]['2024']:null;
    const rank=new SW2.Ranking($('rank'),{onHover:u=>{st.hov=u;draw()},onClick:u=>{st.l=u;draw()}});
    rank.expanded=true;
    const draw=()=>{ const u=st.hov||st.l, n=RC.nasc[u], o=RC.obit[u], yrs=Object.keys(n).map(Number).sort();
      $('place').value=st.l; $('vt').textContent=`${SWD.name(u)}, ${yrs[0]} a ${yrs[yrs.length-1]}`;
      const r=ratio(u);
      $('chg').innerHTML=`<div><small>Nascimentos em 2024</small><b>${SWD.int(n['2024'])}</b></div><div><small>Mortes em 2024</small><b>${SWD.int(o['2024'])}</b></div><div><small>Nascimentos para cada morte</small><b>${r==null?'sem dado':SWD.num(r,2)}</b></div>`;
      SWD.lines($('chart'),{series:[{name:'Nascimentos',pts:yrs.map(y=>[y,n[y]]),c:'var(--accent)',dots:true},{name:'Mortes',pts:yrs.map(y=>[y,o[y]]),c:'var(--d0)',dots:true}],H:340,xs:[yrs[0],2018,2021,yrs[yrs.length-1]],fmt:v=>SWD.mi(v,true),aria:`Nascimentos e mortes registrados em ${SWD.name(u)}`});
      const pn=T.nascP[u], po=T.obitP[u], cross=pn&&Object.keys(pn).map(Number).sort().find(y=>y>2024&&po[y]>=pn[y]), tft=T.tft[u];
      $('proj').innerHTML=`<div class="stamp">${SWD.freq('proj')}<span>Na projeção do IBGE, não é medição</span></div>
        <div style="font-size:22px;font-weight:600;letter-spacing:-.01em;margin-top:6px;text-wrap:pretty">${pn?(cross?`Em ${SWD.name(u)}, as mortes passam os nascimentos em ${cross}.`:`Em ${SWD.name(u)}, os nascimentos seguem acima das mortes até 2060.`):'Sem projeção para este lugar.'}</div>
        <div class="facts"><div class="fact"><span>Filhos por mulher, 2024</span><b>${tft?SWD.num(tft[2024],2):'sem dado'}</b></div><div class="fact"><span>Filhos por mulher, 2060</span><b>${tft?SWD.num(tft[2060],2):'sem dado'}</b></div></div>
        <div style="margin-top:4px">${SWD.stamp('proj')}</div>`;
      rank.render({rows:UF.map(v=>({uf:v,v:ratio(v),txt:ratio(v)==null?'sem dado':SWD.num(ratio(v),2)})),sel:st.l,hov:st.hov,col:'Razão',head:'Estado',plural:'estados'});
    };
    draw();
  }
  renderVals(){ return {}; }
}
